INSERT INTO individual_plan_content (id, individual_plan_id, version_number, processed_date, planned_update_date, likes, dislikes, strengths, aspirations, life_path, additional_info, hygiene, self_care, mobility, diet, home_care, social_contact, activities, health, exercising_rights) VALUES
